{v:'VER',what:'cloud-robust-sh-respawn: a player who dies inside a stronghold in the 2 player DEMO is not thrown through its fence when he comes back near it from outside',
 run:function(){
   if(typeof shOpen!=='function'||typeof shKeep!=='function'||typeof arcadeSoloPick!=='function'||typeof killPlayer!=='function'||typeof render2D!=='function') return 'SKIP: no strongholds here';
   var bad=null, so=0, co=CAREER_ON, R0=render2D, ts, s, p, i, b, r, x, y, placed=0, d1;
   function fr(n){ for(var k=0;k<n;k++){ ts+=50; if(G&&G.player&&!G.player.dying) G.player.hp=Math.max(G.player.hp,90); HID.fromWorker=1; try{ loop(ts); } finally{ HID.fromWorker=0; } } }
   try{
     render2D=function(){};
     __topClear(); __runPrep(); CAREER_ON=0; arcadeSoloPick();
     if(!arcadeDeploy({mapIx:0,seed:1})||!G||!G.arcade||!G.player) return 'SKIP: no arcade raid was built';
     so=ARCADE.solo; ARCADE.solo=0; ts=performance.now()+100000; fr(100);
     if(!G.flow||!G.flow.sh||!G.flow.sh.sites||!G.flow.sh.sites.length) return 'SKIP: no stronghold on seed 1';
     s=G.flow.sh.sites[0]; shOpen(s); p=G.player;
     p.x=s.x; p.y=s.y; p.shS=[0,0,0]; p.shS[s.i]=1; fr(2);
     killPlayer('test');
     for(i=0;i<80&&G.player&&G.player.dying;i++) fr(1);
     p=G.player;
     if(!p||p.dying||G.over) return 'SKIP: the player did not respawn in the 2 player rules';
     if(Math.hypot(p.x-s.x,p.y-s.y)<s.r+400) return 'SKIP: the respawn landed near the compound';
     b=s.ga+Math.PI;
     for(r=s.r+120;r<s.r+390&&!placed;r+=20){ x=s.x+Math.cos(b)*r; y=s.y+Math.sin(b)*r; if(spotFree(G.map,x,y,14)){ p.x=x; p.y=y; p.vx=0; p.vy=0; placed=r; } }
     if(!placed) return 'SKIP: no open floor behind the fence';
     ARCADE.holdT=0; fr(1);
     d1=Math.hypot(p.x-s.x,p.y-s.y);
     if(d1<s.r) bad='came back to '+placed+' from the compound behind its fence and was thrown inside to '+Math.round(d1)+' (fence '+s.r+')';
   } finally {
     render2D=R0;
     try{ ARCADE.solo=so; if(G&&G.arcade&&!G.over) arcadeRaidStop('end'); }catch(_e){}
     CAREER_ON=co; __topClear();
   }
   return bad; }},
